var DATA = {"type": "Grasp (2 fingers)", "model": "Coulomb friction point contacts", "params": "m=1|k=500|c=5|x0=0.05", "criterion": "Force closure with mu=0.4"};
console.log("Contact: " + DATA.type + " | Model: " + DATA.model);
var p = {};
DATA.params.split("|").forEach(function (kv) {
  var parts = kv.split("=").map(function (s) { return s.trim(); });
  if (parts.length === 2) p[parts[0]] = parseFloat(parts[1]);
});
var m = p.m || 1, k = p.k || 100, c = p.c || 2, x = p.x0 || 0.1, v = 0, dt = 0.001, steps = 2000;
// 1D mass-spring-damper contact: m x'' = -k x - c v  (x>0 penetration)
var maxPen = 0;
for (var i = 0; i < steps; i++) {
  var F = -k * x - c * v;
  v += (F / m) * dt; x += v * dt;
  if (x > maxPen) maxPen = x;
  if (x < 0) { x = 0; if (v < 0) v = 0; } // separation
}
console.log("Simulated " + steps + " steps: max penetration=" + maxPen.toFixed(4) + " m, final x=" + x.toFixed(5) + " (rest=" + (Math.abs(x) < 1e-3) + ")");
console.log("Stability criterion: " + DATA.criterion);
console.log("RESULT: contact settled — " + (Math.abs(x) < 1e-3 ? "STABLE" : "CHECK") + ".");

